contracts/15_Complejos_Struct.sol.content:
// SPDX-License-Identifier: GPL-3.0
pragma solidity >=0.8.2 <0.9.0;

contract ComplejosStruct {

    struct Alumno {
        uint256 codigo;
        string nombre;  
        uint256 edad;      
    }

    Alumno[] private alumnos;

    function agregarAlumno(uint256 _codigo, string memory _nombre, uint256 _edad) public {
        alumnos.push(Alumno(_codigo, _nombre, _edad));
    }

    //se puede devolver mas de un resultado
    function mostrarAlumnoV1(uint256 _indice) public view returns(uint256 Codigo, string memory Nombre) {
        //return (421528, "Luis");
        return(alumnos[_indice].codigo, alumnos[_indice].nombre);
    }

    function mostrarAlumnoV2(uint256 _indice) public view returns(uint256 Codigo, string memory Nombre, uint256 Edad) {
        Alumno memory al = alumnos[_indice];
        return(al.codigo, al.nombre, al.edad);
    }

    function mostrarAlumnoV3(uint256 _indice) public view returns(Alumno memory alumno) {
        require(_indice < alumnos.length, "Posicion Incorrecta");
        Alumno memory al = alumnos[_indice];
        return(al);
    }




}

contracts/16_Complejo_Mapping.sol.content:
// SPDX-License-Identifier: GPL-3.0
pragma solidity >=0.8.2 <0.9.0;

contract ComplejosMapping {

    struct Alumno {
        uint256 codigo;
        string nombre;
        uint256 edad;
    }

    mapping(uint256 => Alumno) private alumnos;

    mapping(address => uint256) public saldoCuentas;

    function agregarAlumno(uint256 _codigo, string memory _nombre, uint256 _edad) public {
        //alumnos.push(Alumno(_codigo, _nombre, _edad));
        alumnos[_codigo] = Alumno(_codigo, _nombre, _edad);
    }

    function obtenerEmpleado(uint256 _codigo) public view returns (uint256 Codigo, string memory Nombre, uint256 Edad) {
        Alumno memory al = alumnos[_codigo];
        //require(al.codigo != 0, "Alumno no encontrado");
        return (al.codigo, al.nombre, al.edad);
    }

    function asignarmeSoles(uint256 _monto) public {
        saldoCuentas[msg.sender] = _monto;
    }

    function sumarmeSoles(uint256 _monto) public {
        saldoCuentas[msg.sender] = saldoCuentas[msg.sender] + _monto;
    }

}

contracts/17_PC1_GetCuenta.sol.content:
// SPDX-License-Identifier: GPL-3.0

pragma solidity >=0.8.2 <0.9.0;

contract GetCuenta {

    function obtenerCuenta(string memory codigo) public pure returns (uint256) {

        return uint256(keccak256(abi.encodePacked(codigo))) % 15 + 1;

    }

}

contracts/18_PC1_Examen.sol.content:
// SPDX-License-Identifier: GPL-3.0
pragma solidity >=0.8.2 <0.9.0;

contract Hospital278309 { 
    
    struct Paciente {
        uint256 id;
        string nombre;
        uint256 edad;
        string diagnostico;
        bool estado; 
    }
    
    Paciente[] public pacientes;
    uint256 public posicion;
    address public direccion;
    
    constructor(uint256 _posicion) {
        posicion = _posicion;
        direccion = msg.sender;
    }

    function agregarElemento(uint256 _id, string memory _nombre, uint256 _edad, string memory _diagnostico, bool _estado) public {
        require(_id % 2 == 0, "No se permiten id impares");
        pacientes.push(Paciente(_id, _nombre, _edad, _diagnostico, _estado));
    }

    function contarElementos() public view returns (uint256) {
        return pacientes.length;
    }

    function cambiarDireccion(address _nuevaDireccion) public {
        direccion = _nuevaDireccion;
    }

    
    function inactivarEstado(uint256 _id) public {
        for(uint i = 0; i < pacientes.length; i++) {
            if(pacientes[i].id == _id) {
                pacientes[i].estado = false;
            }
        }
    }
}

